enum BookStatus { AVAILABLE, LOANED, RESERVED, LOST }

class Book {                          // catalog entry (one per title)
    private final String isbn;
    private final String title;
    private final String author;
    private final List<BookItem> copies = new ArrayList<>();   // 1 -> many
}

class BookItem {                      // one physical copy
    private final String barcode;
    private BookStatus status = BookStatus.AVAILABLE;
    boolean isAvailable() { return status == BookStatus.AVAILABLE; }
}

class Member {
    private final String memberId;
    private final List<BookLending> activeLoans = new ArrayList<>();
    private double outstandingFine = 0;
    boolean canBorrow() { return outstandingFine == 0 && activeLoans.size() < 5; }
}

record BookLending(BookItem item, Member member, LocalDate issued, LocalDate due) {}
```
*A `Member` borrows a `BookItem`, not a `Book` — you can only check out a physical copy.*

