class Book implements Observable {
  private Queue<Reservation> reservationQueue = new LinkedList<>();
  private List<Observer> observers = new ArrayList<>(); // notification listeners

  public void addReservation(Member member) {
    reservationQueue.offer(new Reservation(member, this, LocalDateTime.now()));
  }

  public void onBookItemReturned(BookItem item) {
    if (!reservationQueue.isEmpty()) {
      Reservation next = reservationQueue.poll();
      notifyObservers(new ReservationAvailableEvent(next.getMember(), item));
      // or: item.reserveFor(next.getMember());
    }
  }
}

