    List<Book> search(String type, String term) {
        if (type.equals("TITLE"))       return byTitle(term);
        else if (type.equals("AUTHOR")) return byAuthor(term);
        else if (type.equals("ISBN"))   return byIsbn(term);
        // every new criterion edits and retests this method
        throw new IllegalArgumentException(type);
    }
}
