interface SearchStrategy { List<Book> search(List<Book> catalog, String term); }

class SearchByAuthor implements SearchStrategy {
    public List<Book> search(List<Book> catalog, String term) {
        return catalog.stream()
            .filter(b -> b.author().equalsIgnoreCase(term))
            .toList();
    }
}

class LibraryCatalog {
    List<Book> search(SearchStrategy strategy, String term) {
        return strategy.search(books, term);   // delegate; catalog never changes
    }
}
// new criterion (e.g. SearchByGenre) = new class, zero edits here
