interface FineCalculator {
  BigDecimal calculate(BookLending lending, LocalDate returnDate);
}

class StandardFineCalculator implements FineCalculator {
  private static final BigDecimal DAILY_RATE = new BigDecimal("5.00");

  public BigDecimal calculate(BookLending lending, LocalDate returnDate) {
    long overdueDays = ChronoUnit.DAYS.between(
        lending.getDueDate(), returnDate);
    if (overdueDays <= 0) return BigDecimal.ZERO;
    return DAILY_RATE.multiply(BigDecimal.valueOf(overdueDays));
  }
}

sections.content:
```java
interface FineStrategy { BigDecimal dailyRate(); }
class StandardFine implements FineStrategy { public BigDecimal dailyRate() { return new BigDecimal("5"); } }
class PremiumFine  implements FineStrategy { public BigDecimal dailyRate() { return new BigDecimal("2"); } }

class ReturnService {
    BigDecimal returnBook(BookLending loan, LocalDate returnDate, FineStrategy strategy) {
        long overdue = ChronoUnit.DAYS.between(loan.due(), returnDate);
        BigDecimal fine = BigDecimal.ZERO;
        if (overdue > 0) {
            fine = strategy.dailyRate().multiply(BigDecimal.valueOf(overdue));
            loan.member().addFine(fine);            // updates outstanding balance
        }
        loan.item().markAvailable();
        return fine;
    }
}
```
*Rate is pluggable per member tier; `BigDecimal` keeps money exact.*

